object Solution {
  def lengthOfLIS(nums: Array[Int]): Int = {
    import scala.collection.mutable.ArrayBuffer

    val tails = ArrayBuffer[Int]()
    for (num <- nums) {
      // Binary search for the insertion position of num in tails
      var left = 0
      var right = tails.length
      while (left < right) {
        val mid = (left + right) / 2
        if (tails(mid) < num) left = mid + 1
        else right = mid
      }
      if (right == tails.length) tails.append(num)
      else tails(right) = num
    }
    tails.length
  }
}

